static const size_t LANA_LOWER_MAP_COUNT = 1433u;

static inline uint32_t lana_unicode_upper(uint32_t cp) {
    size_t lo = 0u, hi = LANA_UPPER_MAP_COUNT;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (LANA_UPPER_MAP[mid].from < cp) { lo = mid + 1u; }
        else { hi = mid; }
    }
    if (lo < LANA_UPPER_MAP_COUNT && LANA_UPPER_MAP[lo].from == cp) {
        return LANA_UPPER_MAP[lo].to;
    }
    return cp;
}

static inline uint32_t lana_unicode_lower(uint32_t cp) {
    size_t lo = 0u, hi = LANA_LOWER_MAP_COUNT;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (LANA_LOWER_MAP[mid].from < cp) { lo = mid + 1u; }
        else { hi = mid; }
    }
    if (lo < LANA_LOWER_MAP_COUNT && LANA_LOWER_MAP[lo].from == cp) {
        return LANA_LOWER_MAP[lo].to;
    }
    return cp;
}

